+package com.urlshortner.urls;
+
+import jakarta.validation.Constraint;
+import jakarta.validation.ConstraintValidator;
+import jakarta.validation.ConstraintValidatorContext;
+import jakarta.validation.Payload;
+import java.lang.annotation.Retention;
+import java.lang.annotation.Target;
+import java.net.URI;
+import java.net.URISyntaxException;
+import static java.lang.annotation.ElementType.*;
+import static java.lang.annotation.RetentionPolicy.RUNTIME;
+
+@Target({FIELD, PARAMETER, RECORD_COMPONENT, ANNOTATION_TYPE})
+@Retention(RUNTIME)
+@Constraint(validatedBy = Destination.Validator.class)
+public @interface Destination {
+    String message() default "must be an absolute HTTP or HTTPS URL without credentials or control characters";
+    Class<?>[] groups() default {};
+    Class<? extends Payload>[] payload() default {};
+
+    class Validator implements ConstraintValidator<Destination, String> {
+        @Override
+        public boolean isValid(String value, ConstraintValidatorContext context) {
+            return valid(value);
+        }
+
+        public static boolean valid(String value) {
+            if (value == null || value.isBlank() || value.codePoints().anyMatch(Character::isISOControl)) {
+                return false;
+            }
+            try {
+                URI uri = new URI(value).parseServerAuthority();
+                String scheme = uri.getScheme();
+                if (!("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme))
+                        || uri.getHost() == null || uri.getRawUserInfo() != null) {
+                    return false;
+                }
+                int port = uri.getPort();
+                return port >= -1 && port <= 65535 && !uri.getRawAuthority().endsWith(":");
+            } catch (URISyntaxException exception) {
+                return false;
+            }
+        }
+    }
+}
