+package com.urlshortner.urls;
+
+import java.net.URI;
+import org.springframework.beans.factory.annotation.Value;
+import org.springframework.stereotype.Component;
+
+@Component
+public class PublicOrigin {
+    private final String origin;
+
+    public PublicOrigin(@Value("${shortener.public-base-url}") String value) {
+        if (!Destination.Validator.valid(value)) {
+            throw new IllegalArgumentException("Invalid shortener public origin");
+        }
+        URI uri = URI.create(value);
+        String path = uri.getRawPath();
+        if (uri.getRawQuery() != null || uri.getRawFragment() != null
+                || !(path == null || path.isEmpty() || path.equals("/"))) {
+            throw new IllegalArgumentException("Invalid shortener public origin");
+        }
+        origin = value.endsWith("/") ? value.substring(0, value.length() - 1) : value;
+    }
+
+    public String shortUrl(String code) {
+        return origin + "/r/" + code;
+    }
+}
