+package com.urlshortner.urls;
+
+import com.fasterxml.jackson.annotation.JsonInclude;
+import jakarta.validation.Valid;
+import java.time.Instant;
+import org.springframework.http.HttpHeaders;
+import org.springframework.http.ResponseEntity;
+import org.springframework.web.bind.annotation.*;
+
+@RestController
+public class UrlController {
+    public record CreateRequest(@Destination String url) {}
+    public record Created(String code, String shortUrl, String url, Instant createdAt) {}
+    @JsonInclude(JsonInclude.Include.ALWAYS)
+    public record Analytics(String code, String url, Instant createdAt, long clickCount, Instant lastAccessedAt) {}
+    private final UrlService service;
+    private final PublicOrigin origin;
+
+    public UrlController(UrlService service, PublicOrigin origin) {
+        this.service = service;
+        this.origin = origin;
+    }
+
+    @PostMapping("/api/urls")
+    public ResponseEntity<Created> create(@Valid @RequestBody CreateRequest request) {
+        UrlRepository.Entry entry = service.create(request.url());
+        return ResponseEntity.status(201).body(new Created(entry.code(), origin.shortUrl(entry.code()),
+                entry.url(), entry.createdAt()));
+    }
+
+    @GetMapping("/r/{code}")
+    public ResponseEntity<Void> redirect(@PathVariable("code") String code) {
+        return ResponseEntity.status(302).header(HttpHeaders.LOCATION, service.redirect(code))
+                .header(HttpHeaders.CACHE_CONTROL, "no-store").build();
+    }
+
+    @GetMapping("/api/urls/{code}/analytics")
+    public Analytics analytics(@PathVariable("code") String code) {
+        UrlRepository.Entry entry = service.analytics(code);
+        return new Analytics(entry.code(), entry.url(), entry.createdAt(), entry.clickCount(), entry.lastAccessedAt());
+    }
+}
