@@ -0,0 +1,73 @@
+package com.urlshortner.urls;
+
+import java.sql.SQLException;
+import java.time.Instant;
+import java.time.OffsetDateTime;
+import java.util.Optional;
+import org.springframework.dao.DataIntegrityViolationException;
+import org.springframework.jdbc.core.JdbcTemplate;
+import org.springframework.jdbc.core.RowMapper;
+import org.springframework.stereotype.Repository;
+
+@Repository
+public class UrlRepository {
+    public record Entry(String code, String url, Instant createdAt, long clickCount, Instant lastAccessedAt) {}
+
+    public static class CodeCollision extends RuntimeException {
+        public CodeCollision(Throwable cause) { super("Code collision", cause); }
+    }
+
+    private static final RowMapper<Entry> MAPPER = (rs, row) -> {
+        OffsetDateTime accessed = rs.getObject("last_accessed_at", OffsetDateTime.class);
+        return new Entry(rs.getString("code"), rs.getString("url"),
+                rs.getObject("created_at", OffsetDateTime.class).toInstant(),
+                rs.getLong("click_count"), accessed == null ? null : accessed.toInstant());
+    };
+    private final JdbcTemplate jdbc;
+
+    public UrlRepository(JdbcTemplate jdbc) { this.jdbc = jdbc; }
+
+    public Entry insert(String code, String url) {
+        try {
+            return jdbc.queryForObject("INSERT INTO url_service.urls (code, url) VALUES (?, ?) "
+                    + "RETURNING code, url, created_at, click_count, last_accessed_at", MAPPER, code, url);
+        } catch (DataIntegrityViolationException exception) {
+            if (isCodeCollision(exception)) {
+                throw new CodeCollision(exception);
+            }
+            throw exception;
+        }
+    }
+
+    public Optional<Entry> find(String code) {
+        return jdbc.query("SELECT code, url, created_at, click_count, last_accessed_at "
+                + "FROM url_service.urls WHERE code = ?", MAPPER, code).stream().findFirst();
+    }
+
+    public Optional<String> redirect(String code) {
+        return jdbc.query("UPDATE url_service.urls SET click_count = click_count + 1, "
+                + "last_accessed_at = clock_timestamp() WHERE code = ? RETURNING url",
+                (rs, row) -> rs.getString("url"), code).stream().findFirst();
+    }
+
+    static boolean isCodeCollision(Throwable failure) {
+        for (Throwable cause = failure; cause != null; cause = cause.getCause()) {
+            if (cause instanceof SQLException sql) {
+                for (SQLException current = sql; current != null; current = current.getNextException()) {
+                    if (!"23505".equals(current.getSQLState())) { continue; }
+                    // PostgreSQL is runtimeOnly; inspect its structured metadata without a compile dependency.
+                    try {
+                        Object metadata = current.getClass().getMethod("getServerErrorMessage").invoke(current);
+                        if (metadata != null && "urls_code_unique".equals(
+                                metadata.getClass().getMethod("getConstraint").invoke(metadata))) {
+                            return true;
+                        }
+                    } catch (ReflectiveOperationException | SecurityException ignored) {
+                        // Missing metadata must never broaden retry eligibility.
+                    }
+                }
+            }
+        }
+        return false;
+    }
+}
