+package com.urlshortner.urls;
+
+import org.springframework.stereotype.Service;
+
+@Service
+public class UrlService {
+    public static class MissingUrl extends RuntimeException {}
+    public static class AllocationFailure extends RuntimeException {}
+    private final UrlRepository repository;
+    private final CodeGenerator generator;
+
+    public UrlService(UrlRepository repository, CodeGenerator generator) {
+        this.repository = repository;
+        this.generator = generator;
+    }
+
+    public UrlRepository.Entry create(String url) {
+        for (int attempt = 0; attempt < 5; attempt++) {
+            try {
+                return repository.insert(generator.next(), url);
+            } catch (UrlRepository.CodeCollision ignored) {
+                // Each insertion is independent; no surrounding transaction becomes aborted.
+            }
+        }
+        throw new AllocationFailure();
+    }
+
+    public String redirect(String code) {
+        return repository.redirect(code).orElseThrow(MissingUrl::new);
+    }
+
+    public UrlRepository.Entry analytics(String code) {
+        return repository.find(code).orElseThrow(MissingUrl::new);
+    }
+}
