+package com.urlshortner.urls;
+
+import jakarta.validation.Validation;
+import org.junit.jupiter.api.Test;
+import static org.junit.jupiter.api.Assertions.*;
+
+class DestinationRegressionTest {
+    @Test
+    void constraintAndPublicOriginUseSharedValidator() {
+        try (var factory = Validation.buildDefaultValidatorFactory()) {
+            var validator = factory.getValidator();
+            assertTrue(validator.validate(new UrlController.CreateRequest(
+                    "https://example.invalid:443/a%20b?x=1#fragment")).isEmpty());
+            assertFalse(validator.validate(new UrlController.CreateRequest(
+                    "https://user:password@example.invalid")).isEmpty());
+            assertFalse(validator.validate(new UrlController.CreateRequest(null)).isEmpty());
+        }
+        assertEquals("https://short.invalid/r/AAAAAAAA",
