+        assertThrows(IllegalArgumentException.class,
+                () -> new PublicOrigin("https://user:password@short.invalid"));
+        assertThrows(IllegalArgumentException.class,
+                () -> new PublicOrigin("https://short.invalid/path"));
+    }
+}
