+import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
+
+class UrlHttpTest {
+    private UrlRepository repository;
+    private MockMvc mvc;
+
+    @BeforeEach
+    void setUp() {
+        repository = mock(UrlRepository.class);
+        CodeGenerator generator = mock(CodeGenerator.class);
+        when(generator.next()).thenReturn("AAAAAAAA");
+        mvc = MockMvcBuilders.standaloneSetup(new UrlController(new UrlService(repository, generator),
+                new PublicOrigin("https://short.invalid"))).setControllerAdvice(new UrlErrors()).build();
+    }
+
+    @Test
+    void creationIgnoresForwardingHeaders() throws Exception {
+        when(repository.insert("AAAAAAAA", "https://example.invalid/a?x=1#f"))
+                .thenReturn(new UrlRepository.Entry("AAAAAAAA", "https://example.invalid/a?x=1#f", Instant.EPOCH, 0, null));
+        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)
+                .header("Host", "evil.invalid").header("Forwarded", "host=evil.invalid;proto=http")
+                .header("X-Forwarded-Host", "evil.invalid").header("X-Forwarded-Proto", "http")
+                .content("{\"url\":\"https://example.invalid/a?x=1#f\"}"))
+                .andExpect(status().isCreated()).andExpect(jsonPath("$.code").value("AAAAAAAA"))
+                .andExpect(jsonPath("$.shortUrl").value("https://short.invalid/r/AAAAAAAA"))
+                .andExpect(jsonPath("$.url").value("https://example.invalid/a?x=1#f"))
+                .andExpect(jsonPath("$.createdAt").isNotEmpty());
+    }
+
+    @Test
+    void redirectAndAnalyticsContracts() throws Exception {
+        String url = "https://example.invalid/a%20b?x=1#f";
+        when(repository.redirect("AAAAAAAA")).thenReturn(Optional.of(url));
+        when(repository.find("AAAAAAAA")).thenReturn(Optional.of(
+                new UrlRepository.Entry("AAAAAAAA", url, Instant.EPOCH, 0, null)));
+        mvc.perform(get("/api/urls/AAAAAAAA/analytics")).andExpect(status().isOk())
+                .andExpect(jsonPath("$.code").value("AAAAAAAA"))
+                .andExpect(jsonPath("$.url").value(url)).andExpect(jsonPath("$.createdAt").isNotEmpty())
+                .andExpect(jsonPath("$.clickCount").value(0))
+                .andExpect(content().string(org.hamcrest.Matchers.containsString("\"lastAccessedAt\":null")));
+        verify(repository, never()).redirect(anyString());
+        mvc.perform(get("/r/AAAAAAAA")).andExpect(status().isFound())
+                .andExpect(header().string("Location", url)).andExpect(header().string("Cache-Control", "no-store"));
+        verify(repository).redirect("AAAAAAAA");
+    }
+
+    @Test
+    void missingCodes() throws Exception {
+        when(repository.redirect("unknown")).thenReturn(Optional.empty());
+        when(repository.find("unknown")).thenReturn(Optional.empty());
+        mvc.perform(get("/r/unknown")).andExpect(status().isNotFound());
+        mvc.perform(get("/api/urls/unknown/analytics")).andExpect(status().isNotFound());
+        verify(repository, never()).insert(anyString(), anyString());
+    }
+
+    @Test
+    void invalidRequests() throws Exception {
+        // Spring's standalone MVC uses Jakarta Validation from the existing classpath.
+        for (String body : new String[] {"{}", "{\"url\":null}", "{\"url\":\"ftp://example.invalid\"}",
+                "{\"url\":{}}", "{\"url\":\"http://example.invalid/\\n\"}", "{"}) {
+            mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(body))
+                    .andExpect(status().isBadRequest());
+        }
+        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)).andExpect(status().isBadRequest());
+        verifyNoInteractions(repository);
+    }
+
+    @Test
+    void sanitizesFailuresAndExhaustion() throws Exception {
+        when(repository.insert(anyString(), anyString()))
+                .thenThrow(new DataAccessResourceFailureException("private database details"));
+        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)
+                .content("{\"url\":\"https://example.invalid\"}"))
+                .andExpect(status().isInternalServerError())
+                .andExpect(content().json("{\"error\":\"Unable to process request\"}"));
+        reset(repository);
+        when(repository.insert(anyString(), anyString())).thenThrow(new UrlRepository.CodeCollision(null));
+        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)
+                .content("{\"url\":\"https://example.invalid\"}"))
+                .andExpect(status().isInternalServerError())
+                .andExpect(content().json("{\"error\":\"Unable to process request\"}"));
+        verify(repository, times(5)).insert(anyString(), anyString());
+    }
+}
